import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, signal } from '@angular/core';
import { environment } from 'environments/environment';
import { firstValueFrom } from 'rxjs';
import { resolveStepParams } from './batch-param-resolver';
import {
    AppFeature,
    BatchStep,
    getEffectiveSmartBatchSuccessWhen,
    SmartBatch,
    SmartBatchRow,
    SmartBatchRowStatus,
    SmartBatchService,
} from './smart-batch.service';

@Injectable({ providedIn: 'root' })
export class BatchBrowserRunnerService {
    readonly running = signal(false);
    private _abort = false;

    constructor(
        private _http: HttpClient,
        private _smartBatch: SmartBatchService
    ) {}

    stop(): void {
        this._abort = true;
        this.running.set(false);
    }

    async runBatch(
        batch: SmartBatch,
        steps: BatchStep[],
        onBatch: (next: SmartBatch) => void,
        onError?: (error: unknown) => void,
        hooks?: {
            onStepStart?: (info: { step: BatchStep; rowIndex: number }) => void;
            onStepComplete?: (info: { step: BatchStep; rowIndex: number; ok: boolean }) => void;
        }
    ): Promise<void> {
        const batchId = batch._id;
        if (!batchId || this.running()) return;

        this._abort = false;
        this.running.set(true);

        const pending = (batch.rows || []).filter(
            (row) => row.status === 'pending' || row.status === 'processing'
        );

        let current = batch;
        try {
            for (const row of pending) {
                if (this._abort) return;
                current = await this._runRow(batchId, row, steps, current, onBatch, hooks);
            }
        } catch (error) {
            onError?.(error);
        } finally {
            this.running.set(false);
        }
    }

    async retryRowSteps(
        batch: SmartBatch,
        steps: BatchStep[],
        rowIndex: number,
        sequences: number[],
        onBatch: (next: SmartBatch) => void
    ): Promise<SmartBatch> {
        const batchId = batch._id;
        const row = (batch.rows || []).find((item) => item.rowIndex === rowIndex);
        if (!batchId || !row) return batch;

        const wanted = [...new Set(sequences.map(Number).filter(Number.isFinite))];
        const enabled = steps.filter((step) => step.enabled !== false).sort((a, b) => a.sequence - b.sequence);
        const results: Record<number, unknown> = { ...(row.results || {}) };
        const errors = (row.errors || []).filter((error) => !wanted.includes(Number(error.step)));
        let creditsSpent = 0;

        for (const sequence of wanted) {
            delete results[sequence];
        }

        this.running.set(true);
        try {
            const pending = await this._putRow(batchId, rowIndex, {
                status: 'pending',
                results,
                errors,
            });
            onBatch(pending.data);

            for (const sequence of wanted) {
                if (this._abort) break;
                const step = enabled.find((item) => item.sequence === sequence);
                if (!step) continue;
                const outcome = await this._invokeStep(step, row.inputData || {}, results);
                creditsSpent += outcome.credits;
                if (outcome.ok) {
                    results[sequence] = outcome.body;
                    continue;
                }
                if ('message' in outcome) {
                    errors.push({ step: sequence, message: outcome.message, code: outcome.code });
                }
            }

            const status: SmartBatchRowStatus =
                errors.length === 0 ? 'completed' : Object.keys(results).length ? 'partial' : 'failed';
            const res = await this._putRow(batchId, rowIndex, { status, results, errors, creditsSpent });
            onBatch(res.data);
            return res.data;
        } finally {
            this.running.set(false);
            this._abort = false;
        }
    }

    private async _runRow(
        batchId: string,
        row: SmartBatchRow,
        steps: BatchStep[],
        batch: SmartBatch,
        onBatch: (next: SmartBatch) => void,
        hooks?: {
            onStepStart?: (info: { step: BatchStep; rowIndex: number }) => void;
            onStepComplete?: (info: { step: BatchStep; rowIndex: number; ok: boolean }) => void;
        }
    ): Promise<SmartBatch> {
        const enabled = steps.filter((step) => step.enabled !== false).sort((a, b) => a.sequence - b.sequence);
        const results: Record<number, unknown> = { ...(row.results || {}) };
        const errors: { step: number; message: string; code: string }[] = [];
        let creditsSpent = 0;

        for (const step of enabled) {
            if (this._abort) return batch;
            if (results[step.sequence] != null) continue;
            hooks?.onStepStart?.({ step, rowIndex: row.rowIndex });
            const outcome = await this._invokeStep(step, row.inputData || {}, results);
            hooks?.onStepComplete?.({ step, rowIndex: row.rowIndex, ok: outcome.ok });
            creditsSpent += outcome.credits;
            if (outcome.ok) {
                results[step.sequence] = outcome.body;
                continue;
            }
            if ('message' in outcome) {
                errors.push({ step: step.sequence, message: outcome.message, code: outcome.code });
            }
            break;
        }

        const status: SmartBatchRowStatus =
            errors.length === 0 ? 'completed' : Object.keys(results).length ? 'partial' : 'failed';
        const payload = { status, results, errors, creditsSpent };
        const res = await this._putRow(batchId, row.rowIndex, payload);
        onBatch(res.data);
        return res.data;
    }

    private async _putRow(
        batchId: string,
        rowIndex: number,
        payload: {
            status: SmartBatchRow['status'];
            results: Record<number, unknown>;
            errors: { step: number; message: string; code: string }[];
            creditsSpent?: number;
        }
    ) {
        try {
            return await firstValueFrom(this._smartBatch.updateBatchRow(batchId, rowIndex, payload));
        } catch (error) {
            if (!this._isServerSideManaged(error)) throw error;
            await firstValueFrom(this._smartBatch.getBatchProgress(batchId));
            return await firstValueFrom(this._smartBatch.updateBatchRow(batchId, rowIndex, payload));
        }
    }

    private _isServerSideManaged(error: unknown): boolean {
        const http = error as HttpErrorResponse;
        const code = String(http?.error?.code || http?.error?.error?.code || '');
        const message = String(http?.error?.message || http?.message || '');
        return code === 'batch_is_server_side_managed' || message.includes('batch_is_server_side_managed');
    }

    /**
     * `includeCost` makes the endpoint return what it actually billed, the same figure the
     * server-side runner records, so browser-run batches report real spend too.
     */
    private async _invokeStep(
        step: BatchStep,
        inputData: Record<string, unknown>,
        results: Record<number, unknown>
    ): Promise<({ ok: true; body: unknown } | { ok: false; message: string; code: string }) & { credits: number }> {
        const feature = typeof step.appFeature === 'object' ? step.appFeature : null;
        const url = this._featureUrl(feature);
        if (!url) return { ok: false, message: 'Step is missing an AppFeature URL', code: 'MissingFeature', credits: 0 };

        const params = resolveStepParams({
            step,
            dependencies: feature?.dependencies,
            inputData,
            results: results as Record<string, unknown>,
        });
        const method = String(feature?.method || 'GET').toUpperCase();
        const query =
            method === 'GET' || method === 'DELETE'
                ? {
                      ...(method === 'GET'
                          ? Object.fromEntries(
                                Object.entries(params).map(([key, value]) => [key, value == null ? '' : String(value)])
                            )
                          : {}),
                      includeCost: 'true',
                  }
                : undefined;

        try {
            const body = await firstValueFrom(
                this._http.request(method, url, {
                    ...(query ? { params: query } : {}),
                    ...(method === 'GET' ? {} : { body: method === 'DELETE' ? params : { ...params, includeCost: true } }),
                })
            );
            return { ok: true, body: (body as { data?: unknown })?.data ?? body, credits: this._creditsOf(body) };
        } catch (error) {
            return { ...this._stepFailure(error, feature), credits: this._creditsOf((error as HttpErrorResponse)?.error) };
        }
    }

    private _creditsOf(body: unknown): number {
        const value = Number((body as { creditsCharged?: unknown })?.creditsCharged);
        return Number.isFinite(value) && value > 0 ? value : 0;
    }

    private _featureUrl(feature: AppFeature | null): string | null {
        const path = feature?.url || feature?.endpoint;
        if (!path) return null;
        return `${environment.apiUrl}/${String(path).replace(/^\//, '')}`;
    }

    private _stepFailure(
        error: unknown,
        feature: AppFeature | null
    ): { ok: true; body: unknown } | { ok: false; message: string; code: string } {
        const http = error as HttpErrorResponse;
        const code = http?.error?.code || http?.error?.error?.code || 'RequestFailed';
        const rules = feature ? getEffectiveSmartBatchSuccessWhen(feature) : undefined;
        const matched = rules?.some(
            (rule) =>
                rule.httpStatus === http?.status &&
                (!rule.responseCodes?.length || rule.responseCodes.includes(code))
        );
        if (matched) return { ok: true, body: http.error?.data ?? http.error ?? {} };
        return {
            ok: false,
            message: http?.error?.message || http?.message || 'Request failed',
            code,
        };
    }
}
